var levelName = Tama.Args.Get(args, "level", "");
var typeName = Tama.Args.Get(args, "floorType", "");
var comment = Tama.Args.Get(args, "comment", "");
var level = new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().First(l => l.Name == levelName);
var ft = new FilteredElementCollector(doc).OfClass(typeof(FloorType)).Cast<FloorType>().First(f => f.Name == typeName);
var tf = doc.ActiveProjectLocation.GetTotalTransform();
var pts = new List<XYZ>();
foreach (var o in (object[])args["points"]) { var a = (object[])o; var s = new XYZ(Convert.ToDouble(a[0])/0.3048, Convert.ToDouble(a[1])/0.3048, 0); var c = tf.OfPoint(s); pts.Add(new XYZ(c.X, c.Y, level.Elevation)); }
var loop = new CurveLoop();
for (int i = 0; i < pts.Count; i++) loop.Append(Line.CreateBound(pts[i], pts[(i+1)%pts.Count]));
var floor = Floor.Create(doc, new List<CurveLoop>{ loop }, ft.Id, level.Id);
var off = floor.get_Parameter(BuiltInParameter.FLOOR_HEIGHTABOVELEVEL_PARAM); if (off != null && !off.IsReadOnly) off.Set(0.0);
if (!string.IsNullOrEmpty(comment)) floor.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS)?.Set(comment);
doc.Regenerate();
var inv = tf.Inverse;
var check = pts.Select((p,i) => { var sh = inv.OfPoint(p); return new { pt = "P0"+(i+1), E = Math.Round(sh.X*0.3048,3), N = Math.Round(sh.Y*0.3048,3) }; }).ToList();
var area = floor.get_Parameter(BuiltInParameter.HOST_AREA_COMPUTED)?.AsDouble() ?? 0;
return new { floorId = floor.Id.IntegerValue, level = level.Name, type = ft.Name, area_m2 = Math.Round(area*0.092903,2), corners = check };
